"""verify 清单（``--manifest``）加载：JSON 清单 → 等价 :class:`VerifyConfig`。

清单是一个普通 UTF-8 编码的 JSON 对象，``schema_version`` 固定为 1：

- 必填：``run_id``、``duration``、``sources``、``testbenches``、``coverage``；
- 可选：``compile``、``seeds``、``jobs``、``timeout``、``workdir``；
- ``sources`` 为有序路径数组；``testbenches`` 为有序对象数组，每项以
  ``testbench`` 指定文件，可选 ``top``、``name``、``required``、``skip``、
  ``seed``；``coverage`` 含 ``threshold``、``points``；``compile`` 含
  ``include_dirs``、``defines``、``parameters``；
- 相对路径（``sources``、``testbench``、``include_dirs``、``workdir``）
  一律以清单所在目录解析，与启动目录无关；数组顺序即配置顺序；
- 顶层 ``seeds`` 非空时启用多种子矩阵，仍禁止与测试台 ``seed`` 同时生效
  （沿用 verify 既有校验）。

:func:`load_verify_manifest` 只构造等价的 :class:`VerifyConfig`，不执行
编译或仿真；构造后的配置与逐项参数走完全相同的执行、断言与覆盖率解析、
基线比较和 JSON 报告路径。清单不可读、非普通 UTF-8 JSON 对象、
``schema_version`` 不为 1 或含未知键时抛 :class:`InputError`（退出码 2，
不生成或覆盖报告）；其余字段校验沿用既有 :class:`InputError` /
:class:`ValueError` 语义。
"""

import json
import os

from .errors import InputError
from .verification import CoverageConfig, TestSpec, VerifyConfig

#: 当前支持的清单 schema 版本。
MANIFEST_SCHEMA_VERSION = 1

#: 顶层允许的键。
_TOP_LEVEL_KEYS = frozenset({
    "schema_version", "run_id", "duration", "sources", "testbenches",
    "coverage", "compile", "seeds", "jobs", "timeout", "workdir",
})

#: 顶层必填键。
_REQUIRED_KEYS = frozenset({
    "run_id", "duration", "sources", "testbenches", "coverage",
})

#: 测试台条目允许的键（``testbench`` 必填，其余可选）。
_TESTBENCH_KEYS = frozenset({
    "testbench", "top", "name", "required", "skip", "seed",
})

#: coverage 对象允许的键。
_COVERAGE_KEYS = frozenset({"threshold", "points"})

#: compile 对象允许的键。
_COMPILE_KEYS = frozenset({"include_dirs", "defines", "parameters"})


def _reject_unknown_keys(obj, allowed, label):
    """对象含未知键时抛 :class:`InputError`（键名按字典序列出）。"""
    unknown = sorted(set(obj) - allowed)
    if unknown:
        raise InputError(f"{label}含未知键：{', '.join(unknown)}")


def _require_object(value, label):
    """要求 JSON 对象（dict），否则抛 :class:`InputError`。"""
    if not isinstance(value, dict):
        raise InputError(f"{label}必须是 JSON 对象")
    return value


def _require_str_list(value, label):
    """要求字符串数组并返回列表副本，否则抛 :class:`InputError`。"""
    if not isinstance(value, list):
        raise InputError(f"{label}必须是数组")
    for item in value:
        if not isinstance(item, str) or not item.strip():
            raise InputError(f"{label}的元素必须是非空字符串")
    return list(value)


def _resolve(base_dir, path):
    """相对路径按清单目录解析；绝对路径原样保留。"""
    if os.path.isabs(path):
        return path
    return os.path.normpath(os.path.join(base_dir, path))


def _load_json_object(path):
    """读取清单文件并解析为 JSON 对象；任何读取/解析失败均为 InputError。"""
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except OSError as exc:
        raise InputError(f"清单不可读：{path}（{exc}）") from exc
    except UnicodeDecodeError as exc:
        raise InputError(f"清单不是普通 UTF-8 文本：{path}（{exc}）") from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise InputError(f"清单不是合法 JSON：{path}（{exc}）") from exc
    return _require_object(data, "清单")


def _build_testbenches(items, base_dir):
    """把 testbenches 数组转换为有序 :class:`TestSpec` 列表。"""
    if not isinstance(items, list):
        raise InputError("testbenches 必须是数组")
    specs = []
    for index, item in enumerate(items):
        label = f"testbenches[{index}]"
        _require_object(item, label)
        _reject_unknown_keys(item, _TESTBENCH_KEYS, label)
        if "testbench" not in item:
            raise InputError(f"{label} 缺少必填键 testbench")
        testbench = item["testbench"]
        if not isinstance(testbench, str) or not testbench.strip():
            raise InputError(f"{label}.testbench 必须是非空字符串")
        for key in ("top", "name"):
            if key in item and (
                not isinstance(item[key], str) or not item[key].strip()
            ):
                raise InputError(f"{label}.{key} 必须是非空字符串")
        for key in ("required", "skip"):
            if key in item and not isinstance(item[key], bool):
                raise InputError(f"{label}.{key} 必须是布尔值")
        if "seed" in item and (
            isinstance(item["seed"], bool)
            or not isinstance(item["seed"], int)
        ):
            raise InputError(f"{label}.seed 必须是非负整数")
        specs.append(TestSpec(
            testbench=_resolve(base_dir, testbench),
            top=item.get("top"),
            name=item.get("name"),
            required=item.get("required", True),
            skip=item.get("skip", False),
            seed=item.get("seed", 0),
        ))
    return specs


def _build_coverage(obj):
    """构造 :class:`CoverageConfig`；校验失败与 CLI 一样归为 InputError。"""
    _require_object(obj, "coverage")
    _reject_unknown_keys(obj, _COVERAGE_KEYS, "coverage")
    points = obj.get("points", [])
    if not isinstance(points, list):
        raise InputError("coverage.points 必须是数组")
    try:
        return CoverageConfig(
            threshold=obj.get("threshold", 1.0), points=points
        )
    except ValueError as exc:
        raise InputError(str(exc)) from exc


def _build_compile(obj, base_dir):
    """解析 compile 对象，返回 ``(include_dirs, defines, parameters)``。"""
    _require_object(obj, "compile")
    _reject_unknown_keys(obj, _COMPILE_KEYS, "compile")
    include_dirs = [
        _resolve(base_dir, p)
        for p in _require_str_list(
            obj.get("include_dirs", []), "compile.include_dirs"
        )
    ]
    defines = _require_str_list(obj.get("defines", []), "compile.defines")
    parameters = _require_str_list(
        obj.get("parameters", []), "compile.parameters"
    )
    return include_dirs, defines, parameters


def load_verify_manifest(path):
    """加载 verify 清单并返回等价的 :class:`VerifyConfig`。

    只构造配置，不执行编译或仿真；报告输出与基线路径不属于清单内容，
    由调用方（CLI 的 ``--report`` / ``--baseline``，按启动目录解析）
    在返回的配置上另行设置。

    :param path: 清单文件路径（JSON 对象，``schema_version`` 为 1）。
    :raises InputError: 清单不可读、非普通 UTF-8 JSON 对象、
        ``schema_version`` 不为 1、含未知键、缺少必填键或字段非法。
    """
    data = _load_json_object(path)

    schema_version = data.get("schema_version")
    if (
        isinstance(schema_version, bool)
        or not isinstance(schema_version, int)
        or schema_version != MANIFEST_SCHEMA_VERSION
    ):
        raise InputError(
            f"清单 schema_version 必须为 {MANIFEST_SCHEMA_VERSION}，"
            f"收到 {schema_version!r}"
        )

    _reject_unknown_keys(data, _TOP_LEVEL_KEYS, "清单")
    missing = sorted(_REQUIRED_KEYS - set(data))
    if missing:
        raise InputError(f"清单缺少必填键：{', '.join(missing)}")

    # 相对路径以清单所在目录解析（取绝对路径，保证与启动目录无关）。
    base_dir = os.path.dirname(os.path.abspath(path))

    sources = [
        _resolve(base_dir, p)
        for p in _require_str_list(data["sources"], "sources")
    ]
    specs = _build_testbenches(data["testbenches"], base_dir)
    coverage = _build_coverage(data["coverage"])
    include_dirs, defines, parameters = _build_compile(
        data.get("compile", {}), base_dir
    )

    workdir = data.get("workdir", ".")
    if not isinstance(workdir, str) or not workdir.strip():
        raise InputError("workdir 必须是非空字符串")

    # jobs/seeds/timeout/run_id/duration 等字段的类型与取值校验沿用
    # VerifyConfig 及 verify 的既有规则（InputError/ValueError）。
    return VerifyConfig(
        sources=sources,
        testbenches=specs,
        run_id=data["run_id"],
        duration=data["duration"],
        coverage=coverage,
        workdir=_resolve(base_dir, workdir),
        jobs=data.get("jobs", 1),
        seeds=data.get("seeds"),
        timeout=data.get("timeout"),
        include_dirs=include_dirs,
        defines=defines,
        parameters=parameters,
    )

"""验证报告的基线加载与结构化对比（schema v4；v5 报告同样可作基线）。

``verify --baseline PATH`` 把上次 ``verify`` 生成的 JSON 报告作为基线：
先按原流程执行并生成当前结果（执行顺序、种子、产物目录与字段语义均不
受影响），再把当前报告与基线按 name 对齐逐类对比——测试台比
``status``/``reason``，断言比终态 ``status``/``fail_count``，覆盖率比
``status``/``hits``/``hit_testbenches``。

每条差异固定为 ``kind``、``name``、``expected``、``actual`` 四个字段：

- 基线缺失（基线有、当前无）：``expected`` 为基线完整记录，
  ``actual`` 为 ``None``；
- 当前新增（基线无、当前有）：``expected`` 为 ``None``，``actual``
  为当前完整记录；
- 字段差异：``expected``/``actual`` 为对应标量。

差异按类别（testbench、assertion、coverage）顺序排列，类别内按 name
的 Unicode 码点排序；同名的多个字段差异分别保留，不合并。
"""

import json
import os

from .errors import InputError
from .report import (
    VERIFICATION_COMPARISON_SCHEMA_VERSION,
    VERIFICATION_FORMAT,
    VERIFICATION_MULTISEED_SCHEMA_VERSION,
    VERIFICATION_SCHEMA_VERSION,
    sanitize_path,
)

#: 可作为基线读取的报告版本（v3 原始报告、v4 带对比报告与 v5 多种子
#: 报告均可）。
SUPPORTED_BASELINE_SCHEMA_VERSIONS = (
    VERIFICATION_SCHEMA_VERSION,
    VERIFICATION_COMPARISON_SCHEMA_VERSION,
    VERIFICATION_MULTISEED_SCHEMA_VERSION,
)

#: 各类别参与对比的字段；顺序即同名多个字段差异的稳定排列顺序。
_COMPARE_FIELDS = {
    "testbench": ("status", "reason"),
    "assertion": ("status", "fail_count"),
    "coverage": ("status", "hits", "hit_testbenches"),
}

#: 对比类别在 ``mismatches`` 中的排列顺序（映射到报告数组字段名）。
_CATEGORIES = (
    ("testbench", "testbenches"),
    ("assertion", "assertions"),
    ("coverage", "coverage"),
)


def load_baseline_report(path):
    """读取并校验基线报告，返回报告 dict。

    :raises InputError: 基线不存在、不可读、非合法 JSON、不是 rtl-lab
        验证报告或版本不受支持；这些情况不生成或覆盖任何报告。
    """
    if not isinstance(path, str) or not path.strip():
        raise InputError("基线报告路径不能为空")
    if not os.path.isfile(path):
        raise InputError(f"基线报告不存在：{path}")
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as exc:
        raise InputError(f"基线报告不是合法 JSON：{path}") from exc
    except (OSError, UnicodeDecodeError) as exc:
        raise InputError(f"基线报告不可读：{path}") from exc
    if not isinstance(data, dict) or data.get("format") != VERIFICATION_FORMAT:
        raise InputError(f"基线不是 rtl-lab 验证报告：{path}")
    if data.get("schema_version") not in SUPPORTED_BASELINE_SCHEMA_VERSIONS:
        raise InputError(
            f"基线报告版本不受支持：{path}"
            f"（schema_version={data.get('schema_version')!r}）"
        )
    return data


def _compare_category(category, baseline_entries, current_entries):
    """按 name 对齐对比一个类别，返回该类别的差异列表（按 name 码点排序）。"""
    fields = _COMPARE_FIELDS[category]
    base_by_name = {e["name"]: e for e in baseline_entries}
    curr_by_name = {e["name"]: e for e in current_entries}
    diffs = []
    for name in sorted(set(base_by_name) | set(curr_by_name)):
        expected = base_by_name.get(name)
        actual = curr_by_name.get(name)
        if expected is None:
            diffs.append({
                "kind": f"{category}_added",
                "name": name,
                "expected": None,
                "actual": actual,
            })
        elif actual is None:
            diffs.append({
                "kind": f"{category}_missing",
                "name": name,
                "expected": expected,
                "actual": None,
            })
        else:
            for field in fields:
                if expected.get(field) != actual.get(field):
                    diffs.append({
                        "kind": f"{category}_{field}",
                        "name": name,
                        "expected": expected.get(field),
                        "actual": actual.get(field),
                    })
    return diffs


def compare_verification_reports(current, baseline, *, baseline_path, workdir):
    """对比当前报告与基线报告，返回报告的 ``comparison`` 字段值。

    ``baseline`` 为脱敏后的基线路径；``passed`` 为无差异标记；
    ``mismatches`` 为结构化差异列表（无差异时为空）。
    """
    mismatches = []
    for category, key in _CATEGORIES:
        mismatches.extend(_compare_category(
            category, baseline.get(key) or [], current.get(key) or [],
        ))
    return {
        "baseline": sanitize_path(baseline_path, workdir),
        "passed": not mismatches,
        "mismatches": mismatches,
    }

"""解析测试台标准输出中的单行结果。

支持三类记录（均为单行，名称为去除首尾空白后非空的单个 token）：

- ``ASSERT PASS name``
- ``ASSERT FAIL name message``（message 为 name 之后的全部文本，可为空）
- ``COVER name``

断言状态取最后一次结果；失败次数按 FAIL 记录累加；
覆盖率点按命中次数累加。所有映射均按名称首次出现的顺序保存。
"""

import re

#: 三类记录的标记前缀。
ASSERT_PREFIX = "ASSERT PASS "
ASSERT_FAIL_PREFIX = "ASSERT FAIL "
COVER_PREFIX = "COVER "

#: 名称为首个非空白 token；FAIL 的 message 为名称之后的全部文本。
_PASS_RE = re.compile(r"^ASSERT\s+PASS\s+(\S+)\s*$")
_FAIL_RE = re.compile(r"^ASSERT\s+FAIL\s+(\S+)(?:\s+(.*?))?\s*$")
_COVER_RE = re.compile(r"^COVER\s+(\S+)\s*$")


class ResultCollector:
    """按行收集断言与覆盖率结果。"""

    def __init__(self):
        #: name -> {"status": "passed"/"failed", "fail_count": int}
        self.assertions = {}
        #: name -> 命中次数
        self.coverage = {}

    def feed_line(self, line):
        """处理一行（不含行尾换行）。无法识别的行将被忽略。

        标记与名称之间允许任意空白（空格或制表符）。

        :returns: 识别出的记录元组（仅供调试），未识别返回 None。
        """
        fail = _FAIL_RE.match(line)
        if fail:
            name = fail.group(1)
            message = fail.group(2) or ""
            entry = self.assertions.setdefault(
                name, {"status": "failed", "fail_count": 0}
            )
            entry["status"] = "failed"
            entry["fail_count"] += 1
            return ("assert_fail", name, message)

        pas = _PASS_RE.match(line)
        if pas:
            name = pas.group(1)
            entry = self.assertions.setdefault(
                name, {"status": "passed", "fail_count": 0}
            )
            entry["status"] = "passed"
            return ("assert_pass", name)

        cov = _COVER_RE.match(line)
        if cov:
            name = cov.group(1)
            self.coverage[name] = self.coverage.get(name, 0) + 1
            return ("cover", name)

        return None

    def feed_text(self, text):
        """处理整段文本，按 \\n / \\r\\n 分行。"""
        for raw in text.splitlines():
            self.feed_line(raw)

    @property
    def has_failure(self):
        """是否出现过且最终仍处于失败状态的断言。"""
        return any(a["status"] == "failed" for a in self.assertions.values())

"""统一验证报告（schema v3）构建与聚合单测（不调用仿真器）。"""

import pytest

from rtl_lab.report import (
    TB_STATUSES,
    VERIFICATION_FORMAT,
    VERIFICATION_SCHEMA_VERSION,
    build_verification_report,
    ensure_report_writable,
)

def _outcome(name, *, status="passed", reason="passed", required=True,
             top=None, testbench_file=None, assertions=None, coverage=None,
             start="2026-01-01T00:00:00+00:00",
             end="2026-01-01T00:00:01+00:00",
             compile_argv=("/usr/bin/iverilog", "-o", "/w/sim.vvp", "/w/d.v"),
             simulate_argv=("/usr/bin/vvp", "sim.vvp", "+SEED=0")):
    return {
        "name": name,
        "top": top or name,
        "testbench_file": testbench_file or f"/w/tb/{name}.v",
        "status": status,
        "reason": reason,
        "required": required,
        "start_time": start,
        "end_time": end,
        "diagnostics": [],
        "assertions": assertions if assertions is not None else {
            "a1": {"status": "passed", "fail_count": 0}
        },
        "coverage": coverage if coverage is not None else {"c1": 1},
        "commands": {
            "compile": list(compile_argv),
            "simulate": list(simulate_argv),
        },
    }


def _build(outcomes, *, threshold=1.0, points=None, run_id="rid",
           sources=("/w/d.v",), tb_files=None):
    if tb_files is None:
        tb_files = [o["testbench_file"] for o in outcomes]
    return build_verification_report(
        run_id=run_id,
        sources=list(sources),
        testbench_files=tb_files,
        coverage_config={"threshold": threshold, "points": points or []},
        duration="100ns",
        compile_command=(
            outcomes[0]["commands"]["compile"] if outcomes else []
        ),
        simulate_command=(
            outcomes[0]["commands"]["simulate"] if outcomes else []
        ),
        outcomes=outcomes,
        generated_at="2026-01-01T00:00:02+00:00",
        workdir="/w",
        known_paths=(),
    )


def test_shape_and_version_markers():
    data, result = _build([_outcome("t1")])
    assert data["schema_version"] == VERIFICATION_SCHEMA_VERSION
    assert data["format"] == VERIFICATION_FORMAT
    assert list(data.keys()) == [
        "schema_version", "format", "run_id", "result", "generated_at",
        "tool", "config", "compilation", "testbenches", "testbench_summary",
        "assertion_summary", "assertions", "coverage_summary", "coverage",
        "skipped_required",
    ]
    assert result == "passed"
    assert data["run_id"] == "rid"
    assert data["result"] == "passed"
    assert data["generated_at"] == "2026-01-01T00:00:02+00:00"
    tb = data["testbenches"][0]
    assert list(tb.keys()) == [
        "name", "top", "testbench", "status", "reason", "required",
        "start_time", "end_time", "command", "diagnostics", "assertions",
        "coverage",
    ]
    assert tb["testbench"] == "tb/t1.v"


def test_compilation_records_actual_compiled_sources_order():
    data, _ = _build(
        [_outcome("t1")], sources=("/w/src/z.v", "/w/src/a.v")
    )
    assert data["compilation"]["sources"] == ["src/z.v", "src/a.v"]


def test_config_summary_fields():
    data, _ = _build([_outcome("t1")])
    assert data["config"]["duration"] == "100ns"
    assert data["config"]["coverage"] == {"threshold": 1.0, "points": []}
    # 顶层代表性命令已脱敏。
    assert data["config"]["compile"][0] == "iverilog"
    assert data["config"]["simulate"][0] == "vvp"


def test_counts_all_pass():
    data, result = _build([
        _outcome("t1", assertions={
            "a": {"status": "passed", "fail_count": 0},
            "b": {"status": "passed", "fail_count": 0},
        }, coverage={"c1": 1, "c2": 3}),
        _outcome("t2", assertions={
            "a": {"status": "passed", "fail_count": 0},
        }, coverage={"c1": 2}),
    ])
    assert result == "passed"
    assert data["testbench_summary"] == {
        "passed": 2, "failed": 0, "skipped": 0
    }
    # 断言按首次出现顺序合并，fail_count 跨台求和。
    assert [a["name"] for a in data["assertions"]] == ["a", "b"]
    assert data["assertion_summary"] == {
        "total": 2, "passed": 2, "failed": 0, "fail_count": 0
    }
    # 覆盖率点按首次出现顺序：c1 在 t1/t2 均命中，c2 仅 t1。
    assert [c["name"] for c in data["coverage"]] == ["c1", "c2"]
    by = {c["name"]: c for c in data["coverage"]}
    assert by["c1"] == {
        "name": "c1", "status": "hit", "hits": 3, "hit_testbenches": 2
    }
    assert by["c2"] == {
        "name": "c2", "status": "hit", "hits": 3, "hit_testbenches": 1
    }
    summary = data["coverage_summary"]
    assert summary["total_points"] == 2
